const PRODUCT=window.CAMPUSLIFT_PRODUCT||{name:'CampusLift',tagline:'Your campus. Your people. Your ride.'};
const app=document.querySelector('#app');
let ratingSelections=new Map(),ratingSubmissions=new Set(),riderRefreshVersion=0;
let currentUser=null, appConfig={vehicles:{bike:{label:'Bike',icon:'🏍️'},scooty:{label:'Scooty',icon:'🛵'},auto:{label:'Auto',icon:'🛺'},car:{label:'Car',icon:'🚗'}},maps_enabled:false,maps_embed_enabled:false};
const navItems=()=>{const role=currentUser?.role;return [['Home','home'],['How It Works','how'],['My Rides',role==='driver'?'driver-history':'my-rides'],['Drive with CampusLift',role==='driver'?'driver':'register-driver'],['Profile','profile']]};
const icon=(name)=>({home:'⌂',car:'⌁',book:'▧',driver:'◉',user:'◎',history:'◷',chart:'⌁',settings:'⚙'}[name]||'•');
const route=()=>location.hash.slice(1)||'home';
const footer=()=>`<footer class="footer"><div class="wrap"><div class="footer-main"><div><a class="brand" href="#home"><span class="brand-mark">C</span>${esc(PRODUCT.name)}</a><p class="muted" style="margin:14px 0 0">${esc(PRODUCT.tagline)}</p></div><nav class="footer-links" aria-label="Footer navigation"><a href="#how">How it works</a><a href="#my-rides">My rides</a><a href="#register-driver">Drive with CampusLift</a></nav></div><div class="copyright"><span>© 2026 ${esc(PRODUCT.name)}</span><span>Campus rides for your college community.</span></div></div></footer>`;
const header=()=>{const items=navItems(),desktopItems=items.filter(([label])=>label!=='Profile'),logout=currentUser?.role==='admin'?'data-admin-logout':'data-logout';return `<header class="wrap topbar"><a class="brand" href="#${currentUser?.role==='driver'?'driver':currentUser?.role==='rider'?'customer':'home'}"><span class="brand-mark">C</span>${esc(PRODUCT.name)}</a><nav class="navlinks" aria-label="Main navigation">${desktopItems.map(([label,id])=>`<a href="#${id}">${label}</a>`).join('')}</nav><div class="nav-actions">${currentUser?`<a class="btn btn-light btn-sm" href="#profile">Profile</a><button class="btn btn-dark btn-sm" type="button" ${logout}>Log out</button>`:`<a class="btn btn-light btn-sm" href="#login">Log in</a><a class="btn btn-dark btn-sm" href="#register">Create account</a>`}</div><button class="menu-btn" aria-label="Toggle navigation" aria-controls="mobile-navigation" aria-expanded="false">☰</button><nav id="mobile-navigation" class="mobile-nav" aria-label="Mobile navigation">${items.map(([label,id])=>`<a href="#${id}">${label}</a>`).join('')}${currentUser?`<button class="btn btn-light" ${logout}>Log out</button>`:`<a href="#login">Log in</a><a href="#register">Create account</a>`}</nav></header>`};
const shell=(content)=>`${header()}${content}${footer()}`;
const home=()=>shell(`<main><section class="wrap hero"><div class="hero-copy"><div class="eyebrow">Your campus. Your people. Your ride.</div><h1>Where would you like to go?</h1><p class="muted">Campus rides, made simple. Get there with someone from your college community.</p><div class="hero-actions"><a class="btn btn-dark" href="#customer">Book a ride <span aria-hidden="true">→</span></a><a class="btn btn-light" href="#register-driver">Drive with CampusLift</a></div></div><div class="hero-art" role="img" aria-label="Decorative campus route showing a pickup, destination, and CampusLift ride"><div class="map-grid"></div><div class="road"></div><div class="route"></div><span class="pin start"></span><span class="pin end"></span><div class="car">↗</div><div class="map-label label-pick"><b>Campus pickup</b><small>Your starting point</small></div><div class="map-label label-driver"><b>Campus driver</b><small>Rides from your community</small></div><div class="map-label label-match"><div class="avatar">C</div><div><b>CampusLift</b><small>Your campus ride</small></div></div></div></section></main>`);
const howPage=()=>shell(`<main class="wrap page-hero how-page"><div class="eyebrow">Simple campus rides</div><h1>How CampusLift works</h1><p class="muted">A straightforward flow for riders and campus drivers.</p><div class="how-grid"><section class="how-card"><div class="eyebrow">For riders</div><ol><li><b>Enter your destination</b><span>Choose pickup and destination.</span></li><li><b>Book a ride</b><span>Request an available campus driver.</span></li><li><b>Meet your driver</b><span>Verify the ride PIN and follow ride status.</span></li></ol><a class="btn btn-dark" href="#customer">Book a ride</a></section><section class="how-card"><div class="eyebrow">For drivers</div><ol><li><b>Get verified</b><span>Complete driver onboarding for admin review.</span></li><li><b>Go online</b><span>Receive eligible ride requests.</span></li><li><b>Complete rides</b><span>Accept, verify the PIN, and finish the trip.</span></li></ol><a class="btn btn-dark" href="#register-driver">Drive with CampusLift</a></section></div></main>`);
const dashboardNav=(kind)=>`<aside class="side-nav"><div class="eyebrow">Driver space</div>${[['Overview','driver'],['Requests','requests'],['Current ride','driver-active'],['History','driver-history']].map(([n,id],i)=>`<a class="side-link ${i===0?'active':''}" href="#${id}"><span>${icon(i===0?'home':n.toLowerCase().includes('ride')?'car':'history')}</span>${n}</a>`).join('')}</aside>`;
const customer=(ridesOnly=false)=>shell(`<main class="wrap rider-dashboard${ridesOnly?' rides-only':''}"><section class="dash-main rider-main">
  <div class="rider-heading"><div><div class="eyebrow">Campus rides</div><h1>${ridesOnly?'My rides':'Where are you going?'}</h1></div>${ridesOnly?'<a class="rider-history-link" href="#customer">Book a ride <span aria-hidden="true">→</span></a>':'<a class="rider-history-link" href="#my-rides">My rides <span aria-hidden="true">→</span></a>'}</div>
  <div class="rider-booking-grid">
    <section id="booking-panel" class="booking-panel"${ridesOnly?' hidden':''}><form id="ride-form">
      <div class="field location-wrap"><div class="field-label-row"><label for="pickup">Pickup</label><button class="location-use" id="use-current-location" type="button">Use my location</button></div><input class="location-input" id="pickup" name="pickup" data-location="pickup" placeholder="Enter pickup point" maxlength="180" autocomplete="off" required /><div class="suggestions" id="pickup-suggestions"></div></div>
      <div class="field location-wrap rider-destination"><label for="destination">Destination</label><input class="location-input" id="destination" name="destination" data-location="destination" placeholder="Where are you going?" maxlength="180" autocomplete="off" required /><div class="suggestions" id="destination-suggestions"></div></div>
      <div class="field rider-vehicle-field"><label>Available rides</label><div class="vehicle-options" id="vehicle-options" role="group" aria-label="Choose an available ride"></div><select id="vehicle-type" name="vehicle_type" aria-hidden="true" tabindex="-1" class="vehicle-source"></select></div>
      <div id="estimate-card" class="estimate-card"><p id="estimate-details" role="status">Add pickup and destination to continue.</p></div>
      <button id="booking-submit" class="btn book-submit" type="submit" disabled>Find a Ride <span aria-hidden="true">→</span></button>
    </form></section>
    <article id="rider-trip-card" class="live-ride-card" hidden><div class="panel-head"><h2>Your ride</h2><span class="tag" id="rider-status">Searching</span></div><div id="rider-active" class="compact-empty"></div>
      <div id="rider-tracking" hidden><div class="active-map-grid"><section><h3>Pickup → destination</h3><div id="ride-route-map" class="map-preview"><div class="map-label map-help">Route map appears when Google Maps is available.</div></div></section><section><h3>Live driver location</h3><div id="ride-map" class="map-preview"><div class="map-label map-help">Live driver location unavailable.</div></div></section></div><p id="rider-live-location" class="muted live-location-copy" role="status">Live driver location unavailable.</p><div id="rider-safety"></div><a id="google-maps-link" class="btn btn-light btn-sm" target="_blank" rel="noopener" hidden>Open route in Maps</a></div>
    </article>
  </div>
  <details id="rider-history-details" class="rider-history-card"><summary><span>Ride history</span><small id="ride-history-count">Past and completed rides</small></summary><div id="rider-history" class="empty-table">Loading rides…</div></details>
</section></main>`);
const driver=()=>shell(`<main class="wrap dashboard-shell">${dashboardNav('driver')}<section class="dash-main"><div class="dash-title"><div><div class="eyebrow">Driver · ${esc(currentUser?.name||'')}</div><h1>Your driving space</h1><span class="status-dot" id="driver-online-label">Checking availability…</span></div><span class="tag">${esc(currentUser?.vehicle_type||'Vehicle not set')}</span></div><div class="driver-status"><div><div class="eyebrow">Availability</div><strong id="driver-state">Checking…</strong><div id="driver-online-help" class="muted" style="font-size:.9rem">Your status will appear here.</div></div><button class="toggle" id="online-toggle" aria-label="Set driver availability" aria-pressed="false"></button></div><article class="panel" id="driver-requests-panel"><div class="panel-head"><h2>Ride requests</h2><button class="tag" type="button" data-refresh>Refresh</button></div><div id="driver-requests" class="empty-table">Loading requests…</div></article><article class="panel" id="driver-current-panel"><div class="panel-head"><h2>Current ride</h2><span class="tag" id="driver-active-status">No active ride</span></div><div id="driver-active" class="empty-table">Your accepted ride will appear here.</div></article><article class="panel" id="driver-history-panel"><div class="panel-head"><h2>History</h2></div><div id="driver-history" class="empty-table">No rides yet. Completed rides will appear here.</div></article></section></main>`);
const auth=(kind,defaultRole='rider')=>shell(`<main class="wrap auth-layout"><aside class="auth-aside"><a class="brand" href="#home"><span class="brand-mark" style="background:var(--lime);color:var(--green)">C</span>CampusLift</a><div><div class="eyebrow" style="color:var(--lime)">Your campus. Your people. Your ride.</div><h2>${kind==='login'?'Welcome back to CampusLift.':'Create your CampusLift account.'}</h2><p>Built for the people you see every day.</p></div><span style="color:#b4d0c0;font-size:.86rem">Simple rides. Familiar people. Campus first.</span></aside><div class="auth-form-wrap"><form class="auth-form" id="auth-form" data-kind="${kind}"><div class="eyebrow">${kind==='login'?'Your campus account':'Join your campus'}</div><h2>${kind==='login'?'Sign in':'Create account'}</h2><p class="muted">${kind==='login'?'Good to have you back.':'Get moving with your campus community.'}</p>${kind==='register'?`<div class="field"><label for="name">Name</label><input id="name" name="name" placeholder="Your name" maxlength="100" required /></div><div class="field"><label for="register-role">Account role</label><select id="register-role" name="role"><option value="rider" ${defaultRole==='rider'?'selected':''}>Rider</option><option value="driver" ${defaultRole==='driver'?'selected':''}>Driver</option></select></div><div id="driver-fields" ${defaultRole==='driver'?'':'hidden'}><div class="field"><label for="driver-vehicle">Vehicle</label><select id="driver-vehicle" name="vehicle_type" ${defaultRole==='rider'?'disabled':''}>${Object.entries(appConfig.vehicles).map(([key,v])=>`<option value="${esc(key)}">${esc(v.label)}</option>`).join('')}</select></div><div class="field"><label for="driver-license">Driving licence <span class="muted">PDF or photo · up to 5 MB</span></label><input id="driver-license" name="driver_license" type="file" accept="application/pdf,image/jpeg,image/png,image/webp" ${defaultRole==='rider'?'disabled':''} required /></div><div class="field"><label for="driver-selfie">Selfie <span class="muted">Photo · up to 5 MB</span></label><input id="driver-selfie" name="driver_selfie" type="file" accept="image/jpeg,image/png,image/webp" ${defaultRole==='rider'?'disabled':''} required /></div><p class="verification-note">Your profile will stay offline until a campus admin reviews and approves your documents.</p></div>`:''}<div class="field"><label for="email">Email</label><input id="email" name="email" type="email" placeholder="you@example.com" maxlength="254" required autocomplete="email" /></div><div class="field"><label for="password">Password</label><input id="password" name="password" type="password" placeholder="${kind==='register'?'At least 10 characters':'Your password'}" required minlength="${kind==='register'?10:1}" autocomplete="${kind==='register'?'new-password':'current-password'}" /></div><button class="btn btn-dark" type="submit">${kind==='login'?'Sign in':'Create account'} <span>→</span></button><p class="muted" style="font-size:.85rem;text-align:center;margin-top:20px">${kind==='login'?`New to CampusLift? <a href="#register" style="color:var(--green);font-weight:700">Create an account</a>`:`Already registered? <a href="#login" style="color:var(--green);font-weight:700">Sign in</a>`}</p><p style="text-align:center;color:#9aa49d;font-size:.75rem">Your password is stored as a secure hash.</p></form></div></main>`);
const adminPage=()=>`<header class="wrap admin-header"><a class="brand" href="#admin"><span class="brand-mark">C</span><span>CampusLift</span></a><div class="admin-header-title">CampusLift Admin</div><div class="admin-header-actions"><button class="btn btn-light btn-sm" type="button" data-admin-logout hidden>Sign out</button></div></header><main class="wrap page-hero admin-page"><div class="eyebrow">CampusLift Admin</div><h1>Admin Dashboard</h1><div id="admin-content"><form class="auth-form admin-login" id="admin-auth-form"><h2>Administrator sign in</h2><p class="muted">Sign in to review driver applications and campus reports.</p><div class="field"><label for="admin-email">Admin email</label><input id="admin-email" name="email" type="email" required autocomplete="username" /></div><div class="field"><label for="admin-password">Password</label><input id="admin-password" name="password" type="password" required autocomplete="current-password" /></div><button class="btn btn-dark" type="submit">Sign in</button></form></div></main>`;

const profilePage=()=>{if(!currentUser)return shell(`<main class="wrap page-hero profile-page"><div class="eyebrow">Your account</div><h1>Profile</h1><p class="muted">Sign in to view your CampusLift account.</p><a class="btn btn-dark" href="#login">Log in</a></main>`);const role=currentUser.role==='driver'?'Driver':'Rider',driverStatus=currentUser.role==='driver'?(currentUser.driver_verification_status==='verified'?'Verified · eligible to go online':currentUser.driver_verification_status==='suspended'?'Suspended · contact campus admin':currentUser.driver_verification_status==='rejected'?'Not approved · contact campus admin':'Pending admin verification'):'';return shell(`<main class="wrap page-hero profile-page"><div class="eyebrow">Your account</div><h1>Profile</h1><section class="profile-card"><div class="profile-avatar-wrap"><div class="profile-avatar" aria-hidden="true">${esc((currentUser.name||'U').trim().slice(0,1).toUpperCase())}</div><button class="profile-avatar-edit" type="button" disabled aria-label="Profile photo editing is not available yet" title="Photo updates are not available yet">✎</button></div><dl><div><dt>Name</dt><dd>${esc(currentUser.name)}</dd></div><div><dt>Email</dt><dd>${esc(currentUser.email)}</dd></div><div><dt>Account</dt><dd>${role}</dd></div>${currentUser.role==='driver'?`<div><dt>Vehicle</dt><dd>${esc(currentUser.vehicle_type||'Not set')}</dd></div><div><dt>Driver status</dt><dd>${driverStatus}</dd></div>`:''}</dl><button class="btn btn-light" type="button" data-logout>Log out</button></section>${currentUser.role==='rider'?'<p class="muted profile-note">To drive, sign out and create a separate Driver account.</p>':''}</main>`)};
const page=()=>{const r=route();if(r==='home'||r==='features'||r==='about')return home();if(r==='how')return howPage();if(r==='my-rides')return customer(true);if(r==='customer'||r==='active-ride'||r==='history')return customer();if(r==='driver'||r==='requests'||r==='earnings'||r==='driver-history'||r==='driver-active')return driver();if(r==='profile')return profilePage();if(r==='admin')return adminPage();if(r==='login')return auth('login');if(r==='register-driver')return auth('register','driver');if(r==='register')return auth('register');return home()};

let toastTimer, refreshTimer, suggestTimers={}, availabilityTimer=null, driverLocationWatchId=null, driverLocationRideId=null, lastLocationSentAt=0, locationShareMessage='Live location is not being shared.', currentDriverLocation=null;
const api=async(path,options={})=>{const response=await fetch(path,{...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})}});let data={};try{data=await response.json()}catch{}if(!response.ok)throw new Error(data.error||`Request failed (${response.status})`);return data};
const esc=(value)=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rideStatusLabel=status=>({searching:'Searching for driver',driver_assigned:'Driver found',in_progress:'Ride started',completed:'Ride completed',declined:'Driver cancelled the ride',cancelled:'Ride cancelled'}[status]||'Ride status unavailable');
const ratingExperience=ride=>{if(ride.rated_by_me){const score=Number(ride.my_rating)||0;return `<section class="ride-rating"><h3>Thanks for rating your ride.</h3><div class="rating-stars saved-rating" role="img" aria-label="You rated this ride ${score} out of 5 stars">${[1,2,3,4,5].map(n=>`<span class="${n<=score?'selected':''}">${n<=score?'★':'☆'}</span>`).join('')}</div></section>`}const selected=ratingSelections.get(Number(ride.id))||0;return `<section class="ride-rating"><h3>How was your ride?</h3><div class="rating-stars" role="group" aria-label="Rate this ride from 1 to 5 stars">${[1,2,3,4,5].map(n=>`<button class="rating-star ${n<=selected?'selected':''}" type="button" data-rating-score="${n}" data-rating-ride="${ride.id}" aria-label="${n} star${n===1?'':'s'}" aria-pressed="${n===selected}">★</button>`).join('')}</div><button class="btn btn-dark rate-submit" type="button" data-submit-rating="${ride.id}" ${selected&&!ratingSubmissions.has(Number(ride.id))?'':'disabled'}>Rate this ride</button></section>`};
const riderStatusCard=(ride,availableDrivers,driverLocationAvailable=false)=>{const heading=ride.status==='driver_assigned'&&driverLocationAvailable?'Driver is coming':rideStatusLabel(ride.status);const message=ride.status==='searching'?(availableDrivers===0?'No rides available right now. Your request is still active.':'CampusLift is looking for an available driver.'):ride.status==='driver_assigned'?(driverLocationAvailable?'Your driver is on the way to the pickup point.':'Your driver accepted the ride and is getting ready to come to the pickup point.'):ride.status==='in_progress'?'Have a safe trip.':ride.status==='completed'?'You can find this trip in Ride history.':ride.status==='declined'?'Driver cancelled the ride. You can try booking again.':'This ride was cancelled. You can book another ride when ready.';return `<section class="rider-status-card"><h3>${heading}</h3><p>${message}</p>${ride.status==='completed'?ratingExperience(ride):''}</section>`};
const rideRow=(r,mode='rider')=>`<div class="ride-row"><div class="ride-route"><strong>${esc(r.pickup)} → ${esc(r.destination)}</strong><p>Ride #${r.id} · ${mode==='driver'?`Rider ${esc(r.rider_name||'')}`:esc(r.created_at)}</p><p>${esc(appConfig.vehicles[r.vehicle_type]?.label||r.vehicle_type)}${r.estimated_fare!=null?` · ₹${Number(r.estimated_fare).toFixed(0)} upfront`:''}</p>${r.driver_name?`<p>Driver: <b>${esc(r.driver_name)}</b> · ${esc(appConfig.vehicles[r.driver_vehicle_type]?.label||r.driver_vehicle_type||'')} · Vehicle ${esc(r.driver_vehicle_number||'not provided')}${r.driver_verification_status==='verified'?' · <span class="verified-badge">✓ Verified driver</span>':''}${r.driver_rating!=null?` · ★ ${r.driver_rating} (${r.driver_rating_count})`:''}</p>`:''}${mode==='driver'?`<p>Rider: ${r.rider_college_status==='verified'?'<span class="verified-badge">✓ Campus verified</span>':'Campus verification not confirmed'}</p>`:''}${mode==='history'&&r.my_rating?`<p class="ride-saved-rating">Your rating: <span aria-label="${Number(r.my_rating)} out of 5 stars">${'★'.repeat(Number(r.my_rating))}${'☆'.repeat(5-Number(r.my_rating))}</span> · ${Number(r.my_rating)}/5</p>`:''}${mode==='rider'&&r.status==='driver_assigned'&&r.ride_pin?`<p class="ride-pin-display">Ride PIN <strong>${esc(r.ride_pin)}</strong> · share it with your driver at pickup</p>`:''}${mode==='rider'&&r.status==='searching'?`<button class="btn btn-light btn-sm" data-ride-action="cancel" data-id="${r.id}">Cancel request</button>`:''}</div>${mode==='current'&&r.status==='completed'?'':`<span class="tag status-${esc(r.status)}">${esc(mode==='driver'&&r.status==='searching'?'Ride request':rideStatusLabel(r.status))}</span>`}</div>`;
const safetyControls=(ride,role)=>ride&&['driver_assigned','in_progress'].includes(ride.status)?`<div class="safety-controls"><button class="btn btn-light btn-sm" data-share-trip="${ride.id}">Share trip status</button><a class="btn btn-danger btn-sm" href="tel:112">Emergency · call 112</a><button class="btn btn-light btn-sm" data-report-ride="${ride.id}">Report an issue</button></div>`:'';

function toast(message){const el=document.querySelector('#toast');if(!el)return;el.className='toast show';el.textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='toast',3800)}
async function submitRideRating(button){const rideId=Number(button.dataset.submitRating),score=ratingSelections.get(rideId);if(!Number.isInteger(score)||score<1||score>5||ratingSubmissions.has(rideId))return;ratingSubmissions.add(rideId);button.disabled=true;try{await api(`/api/rides/${rideId}/rating`,{method:'POST',body:JSON.stringify({score})});ratingSelections.delete(rideId);++riderRefreshVersion;const form=document.querySelector(`[data-submit-rating="${rideId}"]`)?.closest('.ride-rating');if(form)form.outerHTML=ratingExperience({id:rideId,rated_by_me:true,my_rating:score});toast('Thanks for rating your ride.');await riderRefresh()}catch{toast("Couldn't submit your rating. Please try again.")}finally{ratingSubmissions.delete(rideId);if(button.isConnected)button.disabled=!ratingSelections.has(rideId)}}
async function filePayload(input,label,imagesOnly=false){
  const file=input?.files?.[0];if(!file)throw new Error(`Choose a ${label} file.`);
  if(file.size>5*1024*1024)throw new Error(`${label} must be 5 MB or smaller.`);
  const allowed=imagesOnly?['image/jpeg','image/png','image/webp']:['application/pdf','image/jpeg','image/png','image/webp'];
  if(!allowed.includes(file.type))throw new Error(`Choose a supported ${label} file.`);
  const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(new Error(`Could not read the ${label} file.`));reader.readAsDataURL(file)});
  return {mime_type:file.type,data:dataUrl.split(',')[1]||''};
}
function useCurrentLocation(button){
  const pickup=document.querySelector('#pickup');if(!pickup)return;
  if(!window.isSecureContext||!navigator.geolocation){toast('Location access needs HTTPS, or localhost on this device. You can enter a pickup manually.');return;}
  button.disabled=true;const oldText=button.textContent;button.textContent='Finding location…';
  navigator.geolocation.getCurrentPosition(position=>{
    const lat=position.coords.latitude.toFixed(5),lng=position.coords.longitude.toFixed(5);
    pickup.value=`Current location (${lat}, ${lng})`;pickup.dataset.placeId='';pickup.dispatchEvent(new Event('input',{bubbles:true}));
    button.textContent='Location added';setTimeout(()=>{if(button.isConnected){button.textContent=oldText;button.disabled=false}},1800);
  },error=>{
    toast(error.code===1?'Allow location access to use your current pickup.':error.code===3?'Could not get your location in time. Try again.':'Your location is unavailable. Enter a pickup manually.');
    button.textContent=oldText;button.disabled=false;
  },{enableHighAccuracy:true,maximumAge:30000,timeout:12000});
}

function estimateStatus(message){const box=document.querySelector('#estimate-details');if(box)box.textContent=message}
function updateBookingButton(){const button=document.querySelector('#booking-submit'),pickup=document.querySelector('#pickup'),destination=document.querySelector('#destination'),choice=document.querySelector('.vehicle-choice.selected'),availability=window.campusLiftAvailability?.by_vehicle||{};if(!button||!pickup||!destination)return;const ready=!!pickup.value.trim()&&!!destination.value.trim()&&!!choice&&Number(availability[choice.dataset.vehicleChoice]||0)>0;button.disabled=!ready;button.innerHTML=`${window.quickRideEstimate?.available||(!appConfig.maps_enabled&&ready)?'Book Ride':'Find a Ride'} <span aria-hidden="true">→</span>`}
function setOnlineDrivers(count){const value=Number(count)||0;const number=document.querySelector('#online-count'),label=document.querySelector('#online-label');if(number)number.textContent=value;if(label)label.textContent=value===1?'driver online':'drivers online'}
function renderMap(url){const map=document.querySelector('#ride-route-map');if(!map||!url)return;window.campusLiftRouteMapUrl=url;map.innerHTML=`<iframe title="CampusLift pickup to destination route" loading="lazy" src="${url}"></iframe>`}
