function updateGoogleMapsLink(origin,destination){const link=document.querySelector('#google-maps-link');if(!link)return;const pickup=document.querySelector('#pickup')?.value?.trim(),drop=document.querySelector('#destination')?.value?.trim(),from=origin||pickup,to=destination||drop;if(!from||!to){link.hidden=true;return}const params=new URLSearchParams({api:'1',origin:from,destination:to,travelmode:'driving'});link.href=`https://www.google.com/maps/dir/?${params.toString()}`;link.hidden=false}
function prepareRiderTracking(){const routeMap=document.querySelector('#ride-route-map'),liveMap=document.querySelector('#ride-map'),tracking=document.querySelector('#rider-tracking');if(!routeMap||!liveMap||!tracking)return;if(!window.campusLiftRouteMapUrl)routeMap.querySelector('.map-help')?.replaceChildren('Route map unavailable. You can still use the ride and open directions in Maps.');liveMap.querySelector('.map-help')?.replaceChildren('Live driver location unavailable.');if(!document.querySelector('#rider-live-location')){const status=document.createElement('p');status.id='rider-live-location';status.className='muted live-location-copy';status.setAttribute('role','status');status.textContent='Live driver location unavailable.';liveMap.after(status)}if(!document.querySelector('#google-maps-link')){const link=document.createElement('a');link.id='google-maps-link';link.className='btn btn-light btn-sm';link.target='_blank';link.rel='noopener noreferrer';link.textContent='Open route in Google Maps';link.hidden=true;tracking.append(link)}updateGoogleMapsLink()}
function setDriverLocationStatus(message){locationShareMessage=message;const el=document.querySelector('#driver-location-status');if(el)el.textContent=message}
function stopLocalLocationWatch(){if(driverLocationWatchId!==null&&navigator.geolocation)navigator.geolocation.clearWatch(driverLocationWatchId);driverLocationWatchId=null;driverLocationRideId=null;lastLocationSentAt=0}
