function render(){clearInterval(refreshTimer);const r=route();const titles={profile:'CampusLift — Profile','my-rides':'CampusLift — My Rides',how:'CampusLift — How It Works',admin:'CampusLift — Admin',customer:'CampusLift — Book a Ride','active-ride':'CampusLift — Active Ride',history:'CampusLift — Ride History',driver:'CampusLift — Driver',requests:'CampusLift — Ride Requests','driver-history':'CampusLift — Driver Ride History','driver-active':'CampusLift — Current Ride',earnings:'CampusLift — Earnings',login:'CampusLift — Sign in',register:'CampusLift — Create account','register-driver':'CampusLift — Become a Driver'};document.title=titles[r]||'CampusLift';if(r==='admin'){app.innerHTML=page();renderAdmin();return}if(r==='profile'){app.innerHTML=`${header()}<main class="wrap page-hero"><p>Loading profile…</p></main>`;api('/api/auth/me').then(({user})=>{currentUser=user;app.innerHTML=page()}).catch(()=>{currentUser=null;app.innerHTML=page()});return}const neededRole=['customer','my-rides','active-ride','history'].includes(r)?'rider':['driver','requests','earnings','driver-history','driver-active'].includes(r)?'driver':null;if(!neededRole){app.innerHTML=page();if(r==='customer')setupRider();return}app.innerHTML=`${header()}<main class="wrap page-hero"><p>Checking your CampusLift account…</p></main>`;api('/api/auth/me').then(({user})=>{if(!user){currentUser=null;location.hash='login';return}currentUser=user;if(user.role!==neededRole){location.hash=dashboardRoute(user.role);return}app.innerHTML=page();if(neededRole==='rider'){setupRider();if(['history','my-rides'].includes(route()))document.querySelector('#rider-history-details')?.setAttribute('open','')}refreshPage();refreshTimer=setInterval(refreshPage,2500)}).catch(error=>{const missingApi=error.message==='Endpoint not found';const heading=missingApi?'CampusLift server needs a restart':'Could not connect to CampusLift';const message=missingApi?'This page reached a server without the account API. Stop the current server, start server.py from C:\\Users\\somya\\QuickRideCollegePortal, then reload.':`The account API could not be reached: ${error.message}`;app.innerHTML=`${header()}<main class="wrap page-hero"><h1>${heading}</h1><p>${esc(message)}</p><a class="btn btn-light" href="#home">Back to home</a> <button class="btn btn-dark" type="button" onclick="location.reload()">Reload page</button></main>`})}

document.addEventListener('input',e=>{const input=e.target.closest('.location-input');if(!input)return;const key=input.dataset.location;clearTimeout(suggestTimers[key]);suggestTimers[key]=setTimeout(()=>showSuggestions(input),350);if(!input.dataset.sessionToken)input.dataset.sessionToken=window.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;window.quickRideEstimate=null;window.campusLiftQuotes={};document.querySelectorAll('[data-vehicle-fare]').forEach(el=>el.textContent='');const pickup=document.querySelector('#pickup')?.value.trim(),destination=document.querySelector('#destination')?.value.trim();estimateStatus(pickup&&destination&&!appConfig.maps_enabled?'Prices are unavailable right now. You can still request a ride.':'Enter pickup and destination to see available rides.');clearTimeout(availabilityTimer);availabilityTimer=setTimeout(()=>void refreshRiderAvailability(),350);updateBookingButton()});
document.addEventListener('change',e=>{if(e.target.id==='register-role'){const fields=document.querySelector('#driver-fields'),disabled=e.target.value!=='driver';fields.hidden=disabled;fields.querySelectorAll('input,select').forEach(control=>control.disabled=disabled)}if(e.target.id==='vehicle-type')updateEstimate()});
document.addEventListener('click',e=>{const button=e.target.closest('#use-current-location');if(button)useCurrentLocation(button)});
document.addEventListener('click',async e=>{const vehicleChoice=e.target.closest('[data-vehicle-choice]');if(vehicleChoice){if(vehicleChoice.disabled)return;const type=document.querySelector('#vehicle-type');type.value=vehicleChoice.dataset.vehicleChoice;document.querySelectorAll('[data-vehicle-choice]').forEach(b=>{b.classList.toggle('selected',b===vehicleChoice);b.setAttribute('aria-pressed',String(b===vehicleChoice))});updateEstimate();return}const goBtn=e.target.closest('[data-go]');if(goBtn){location.hash=goBtn.dataset.go;return}const menu=e.target.closest('.menu-btn');if(menu){const nav=document.querySelector('.mobile-nav');nav.classList.toggle('open');menu.setAttribute('aria-expanded',nav.classList.contains('open'));menu.textContent=nav.classList.contains('open')?'×':'☰';return}const pick=e.target.closest('[data-select-location]');if(pick){const input=document.querySelector(`#${pick.dataset.selectLocation}`),token=input.dataset.sessionToken||'';let selectedLabel=pick.dataset.label,selectedPlaceId='';try{const place=await api(`/api/maps/place?place_id=${encodeURIComponent(pick.dataset.placeId)}&session_token=${encodeURIComponent(token)}`);selectedLabel=place.formatted_address||selectedLabel;selectedPlaceId=place.place_id||pick.dataset.placeId}catch(error){toast(`${error.message} You can keep this as a manual location.`)}input.value=selectedLabel;input.dataset.placeId=selectedPlaceId;delete input.dataset.sessionToken;document.querySelector(`#${pick.dataset.selectLocation}-suggestions`).innerHTML='';updateEstimate();return}if(e.target.closest('[data-refresh]')){refreshPage();return}if(e.target.closest('[data-logout]')){try{await api('/api/auth/logout',{method:'POST',body:'{}'})}catch{}currentUser=null;ratingSelections.clear();clearInterval(refreshTimer);location.hash='home';toast('You are signed out.');return}if(e.target.closest('[data-admin-logout]')){try{await api('/api/admin/logout',{method:'POST',body:'{}'})}catch{}currentUser=null;renderAdmin();return}const resolve=e.target.closest('[data-resolve-report]');if(resolve){await api(`/api/admin/reports/${resolve.dataset.resolveReport}/resolve`,{method:'POST',body:'{}'});await renderAdmin();return}const star=e.target.closest('[data-rating-score]');if(star){const rideId=Number(star.dataset.ratingRide),score=Number(star.dataset.ratingScore);if(!ratingSubmissions.has(rideId)&&score>=1&&score<=5){ratingSelections.set(rideId,score);const card=star.closest('.ride-rating');card.querySelectorAll('[data-rating-score]').forEach(item=>{const selected=Number(item.dataset.ratingScore)===score;item.classList.toggle('selected',Number(item.dataset.ratingScore)<=score);item.setAttribute('aria-pressed',String(selected))});const submit=card.querySelector('[data-submit-rating]');if(submit)submit.disabled=false}return}const submitRating=e.target.closest('[data-submit-rating]');if(submitRating){await submitRideRating(submitRating);return}const report=e.target.closest('[data-report-ride]');if(report){const description=prompt('Describe the issue. For immediate danger, call 112.');if(description&&description.trim().length>=5){try{await api(`/api/rides/${report.dataset.reportRide}/report`,{method:'POST',body:JSON.stringify({category:'ride_issue',description:description.trim()})});toast('Report sent to campus administrators. For immediate danger, call 112.')}catch(error){toast(error.message)}}return}const share=e.target.closest('[data-share-trip]');if(share){const rideId=Number(share.dataset.shareTrip),ride=(await api('/api/rides')).rides.find(item=>item.id===rideId);if(ride){const text=`${PRODUCT.name} trip status: ${ride.pickup} to ${ride.destination}. Status: ${ride.status.replaceAll('_',' ')}. For emergencies call 112.`;try{if(navigator.share)await navigator.share({title:`${PRODUCT.name} trip`,text});else{await navigator.clipboard.writeText(text);toast('Trip status copied.')}}catch(error){if(error.name!=='AbortError')toast('Could not share trip status on this device.')}}return}const toggle=e.target.closest('#online-toggle');if(toggle){toggle.disabled=true;try{await api('/api/driver/availability',{method:'POST',body:JSON.stringify({online:toggle.getAttribute('aria-pressed')!=='true'})});await driverRefresh();toast('Availability updated.')}catch(error){toast(error.message)}finally{toggle.disabled=false}return}const action=e.target.closest('[data-ride-action]');if(action){action.disabled=true;try{let body={};if(action.dataset.rideAction==='start'){const pin=prompt('Enter the 4-digit Ride PIN shown to the rider:');if(pin===null){action.disabled=false;return}body={pin}}const result=await api(`/api/rides/${action.dataset.id}/${action.dataset.rideAction}`,{method:'POST',body:JSON.stringify(body)});toast(`Ride #${result.ride.id}: ${result.ride.status.replaceAll('_',' ')}.`);await refreshPage()}catch(error){toast(error.message==='Ride PIN is incorrect.'?'That Ride PIN did not match. Please check it and try again.':'Something went wrong. Please try again.');await refreshPage()}}});
document.addEventListener('click',async e=>{
  const action=e.target.closest('[data-driver-review-action]');if(!action||action.disabled)return;
  action.disabled=true;
  try{await api(`/api/admin/drivers/${action.dataset.driverId}/verification`,{method:'POST',body:JSON.stringify({status:action.dataset.driverReviewAction})});toast(action.dataset.driverReviewAction==='verified'?'Driver approved.':'Driver access restricted.');await renderAdmin()}
  catch(error){toast(error.message)}finally{if(action.isConnected)action.disabled=false}
});
document.addEventListener('submit',async e=>{
  const adminForm=e.target.closest('#admin-auth-form');
  if(adminForm){e.preventDefault();const button=adminForm.querySelector('[type=submit]'),data=Object.fromEntries(new FormData(adminForm));button.disabled=true;try{await api('/api/admin/login',{method:'POST',body:JSON.stringify(data)});await renderAdmin()}catch(error){toast(error.message)}finally{button.disabled=false}return}
  const college=e.target.closest('[data-admin-college]');
  if(college){e.preventDefault();const button=college.querySelector('[type=submit]'),data=Object.fromEntries(new FormData(college));button.disabled=true;try{await api(`/api/admin/users/${college.dataset.adminCollege}/college-verification`,{method:'POST',body:JSON.stringify(data)});toast('College verification saved.');await renderAdmin()}catch(error){toast(error.message)}finally{button.disabled=false}return}
  const form=e.target.closest('#auth-form');
  if(form){
    e.preventDefault();const button=form.querySelector('[type=submit]'),data=new FormData(form);button.disabled=true;
    try{
      const payload=Object.fromEntries(data.entries());
      if(form.dataset.kind==='register'&&payload.role==='driver'){
        payload.driver_license=await filePayload(form.querySelector('[name=driver_license]'),'driving licence');
        payload.driver_selfie=await filePayload(form.querySelector('[name=driver_selfie]'),'selfie',true);
      }else{delete payload.driver_license;delete payload.driver_selfie;delete payload.vehicle_type;delete payload.vehicle_number}
      const result=await api(form.dataset.kind==='register'?'/api/auth/register':'/api/auth/login',{method:'POST',body:JSON.stringify(payload)});
      currentUser=result.user;location.hash=dashboardRoute(currentUser.role);toast(form.dataset.kind==='register'?'Account created. You are signed in.':'Welcome back.');
    }catch(error){toast(error.message)}finally{button.disabled=false}return;
  }
  const rideForm=e.target.closest('#ride-form');
  if(rideForm){
    e.preventDefault();const button=rideForm.querySelector('[type=submit]'),pickup=document.querySelector('#pickup'),destination=document.querySelector('#destination');button.disabled=true;
    try{
      const chosenVehicle=document.querySelector('#vehicle-type').value;
      const summary=await api('/api/market/summary');window.campusLiftAvailability=summary;renderVehicleOptions(summary);
      if(!Number(summary.by_vehicle?.[chosenVehicle]||0)){estimateStatus(Number(Object.values(summary.by_vehicle||{}).reduce((a,b)=>a+Number(b||0),0))?'That ride is no longer available. Choose a currently available ride.':'No rides available right now.');return}
      const data=new FormData(rideForm);
      const result=await api('/api/rides',{method:'POST',body:JSON.stringify({pickup:data.get('pickup'),destination:data.get('destination'),vehicle_type:chosenVehicle,...(pickup.dataset.placeId&&destination.dataset.placeId?{pickup_place_id:pickup.dataset.placeId,destination_place_id:destination.dataset.placeId}:{})})});
      window.quickRideEstimate=null;toast(`Ride #${result.ride.id} requested.`);await riderRefresh();
    }catch(error){toast("Couldn't book the ride. Please try again.")}finally{button.disabled=false}
  }
});
window.addEventListener('hashchange',render);
window.addEventListener('hashchange',()=>{if(driverLocationWatchId!==null&&!['driver','requests','earnings','driver-active','driver-history'].includes(route()))void stopDriverLocationSharing()});
document.addEventListener('input',e=>{if(e.target.matches('#pickup,#destination'))updateGoogleMapsLink()});
document.addEventListener('click',async e=>{const button=e.target.closest('[data-location-action]');if(!button)return;const rideId=Number(button.dataset.id);button.disabled=true;if(button.dataset.locationAction==='start'){setDriverLocationStatus('Requesting device location permission…');startDriverLocationSharing(rideId);await driverRefresh()}else{await stopDriverLocationSharing(rideId);await driverRefresh()}});
render();
